import test from 'node:test';import assert from 'node:assert/strict';
import {createCalendarHandler,encrypt,decrypt,ORIGIN,validateEvent} from '../../lumi-calendar/calendar.mjs';
import {withCalendar} from '../../lumi-calendar/calendar-worker.mjs';
import {patchCalendarApp,CALENDAR_FRONTEND} from '../../lumi-calendar/calendar-frontend.mjs';
import {JSDOM} from '../../ativa-demo/node_modules/jsdom/lib/api.js';
const time=Date.parse('2026-10-16T12:00:00Z'),event={title:'Teste fictício',start:'2026-10-17T15:00:00-03:00',end:'2026-10-17T16:00:00-03:00'};
function fixture(){let calendarItems=[],clock=time,scope='https://www.googleapis.com/auth/calendar.events',user='alice',failure=0,refresh=0;const map=new Map(),created=new Map(),calls=[];const env={Memory:{get:async(k,t)=>{const s=map.get(k);return t==='json'&&s?JSON.parse(s):s||null;},put:async(k,v)=>map.set(k,v),delete:async k=>map.delete(k)},GOOGLE_CLIENT_ID:'client',GOOGLE_CLIENT_SECRET:'secret-test',CALENDAR_SESSION_SECRET:'x'.repeat(40)};
 const fetcher=async(url,options={})=>{calls.push({url,options});if(url.includes('tokeninfo'))return Response.json({aud:'client',scope});if(url==='https://oauth2.googleapis.com/token'){refresh++;return Response.json({access_token:'access',refresh_token:'refresh',scope,expires_in:3600});}if(failure)return Response.json({}, {status:failure});if(new URL(url).pathname.endsWith('/events')&&options.method!=='POST')return Response.json({items:[...calendarItems,...created.values()],timeZone:'America/Sao_Paulo'});if(options.method==='POST'){const payload=JSON.parse(options.body);if(created.has(payload.id))return Response.json({}, {status:409});created.set(payload.id,payload);return Response.json({...payload,htmlLink:'https://www.google.com/calendar/event?eid=test'});}const id=url.split('/').pop();return Response.json(created.get(id)||{}, {status:created.has(id)?200:404});};
 const handler=createCalendarHandler({fetcher,verify:async token=>token==='valid-session'?{id:user}:null,now:()=>clock});const req=(path,body,headers={})=>new Request(ORIGIN+path,{method:body===undefined?'GET':'POST',headers:{origin:ORIGIN,authorization:'Bearer valid-session','content-type':'application/json',...headers},...(body===undefined?{}:{body:JSON.stringify(body)})});
 return {env,map,calls,created,req,handler,init:async()=>env.Memory.put('google:tokens:user:alice',await encrypt(env,{access_token:'access',refresh_token:'refresh',expires_at:time+3600000,scope})),scope:v=>scope=v,user:v=>user=v,clock:v=>clock=v,failure:v=>failure=v,items:v=>calendarItems=v,refresh:()=>refresh};}
async function draft(f){await f.init();const r=await f.handler(f.req('/calendar/events/prepare',event),f.env);assert.equal(r.status,202);return r.json();}
test('Calendar requires verified identity, exact origin and bounded valid input',async()=>{const f=fixture();await f.init();for(const [h,status]of [[{authorization:''},401],[{authorization:'Bearer invalid'},401],[{origin:'https://evil.test'},403]])assert.equal((await f.handler(f.req('/calendar/events',event,h),f.env)).status,status);assert.equal((await f.handler(f.req('/calendar/events',{...event,calendarId:'someone-else'}),f.env)).status,400);assert.equal(f.created.size,0);});
test('prepare never writes Google; explicit confirmation is required and details are server-stored',async()=>{const f=fixture(),d=await draft(f);assert.equal(d.created,false);assert.equal(f.created.size,0);const request={confirmationId:d.confirmationId};assert.equal((await f.handler(f.req('/calendar/events/confirm',request),f.env)).status,400);assert.equal((await f.handler(f.req('/calendar/events/confirm',{...request,confirmed:true,title:'changed'}),f.env)).status,400);const r=await f.handler(f.req('/calendar/events/confirm',{...request,confirmed:true}),f.env);assert.equal(r.status,200);assert.equal((await r.json()).created,true);assert.equal(f.created.size,1);assert.ok([...f.map.values()].every(x=>!x.includes(event.title)));});
test('cross-user draft, cancelled draft and expired confirmation cannot create events',async()=>{const f=fixture(),d=await draft(f);f.user('bob');assert.equal((await f.handler(f.req('/calendar/events/confirm',{confirmationId:d.confirmationId,confirmed:true}),f.env)).status,409);f.user('alice');await f.handler(f.req('/calendar/events/cancel',{confirmationId:d.confirmationId}),f.env);assert.equal((await f.handler(f.req('/calendar/events/confirm',{confirmationId:d.confirmationId,confirmed:true}),f.env)).status,409);const d2=await draft(f);f.clock(time+600001);assert.equal((await f.handler(f.req('/calendar/events/confirm',{confirmationId:d2.confirmationId,confirmed:true}),f.env)).status,409);assert.equal(f.created.size,0);});
test('same request and concurrent confirmations use one deterministic Google event ID',async()=>{const f=fixture(),d=await draft(f),body={confirmationId:d.confirmationId,confirmed:true};const rs=await Promise.all([f.handler(f.req('/calendar/events/confirm',body),f.env),f.handler(f.req('/calendar/events/confirm',body),f.env)]);assert.ok(rs.every(r=>r.status===200));assert.equal(f.created.size,1);const d2=await draft(f),r=await f.handler(f.req('/calendar/events/confirm',{confirmationId:d2.confirmationId,confirmed:true}),f.env);assert.equal((await r.json()).duplicate,true);assert.equal(f.created.size,1);});
test('readonly grant, revoked permission and Google failures never report success; English errors',async()=>{const f=fixture();await f.init();f.scope('https://www.googleapis.com/auth/calendar.readonly');let r=await f.handler(f.req('/calendar/events',event,{'accept-language':'en-US'}),f.env);assert.equal(r.status,403);assert.match((await r.json()).error,/Reconnect/);f.scope('https://www.googleapis.com/auth/calendar.events');const d=await draft(f);for(const status of [401,403,500]){f.failure(status);r=await f.handler(f.req('/calendar/events/confirm',{confirmationId:d.confirmationId,confirmed:true}),f.env);assert.equal(r.status,status===500?503:403);assert.equal((await r.json()).created,undefined);}assert.equal(f.created.size,0);});
test('expired access token refreshes server-side without exposing credentials',async()=>{const f=fixture();await f.init();await f.env.Memory.put('google:tokens:user:alice',await encrypt(f.env,{refresh_token:'refresh',expires_at:0}));const r=await f.handler(f.req('/calendar/events',event),f.env);assert.equal(r.status,202);assert.equal(f.refresh(),1);assert.ok(!(await r.text()).includes('access_token'));});
test('OAuth state is browser-bound, PKCE protected, consumed and scope checked',async()=>{const f=fixture();let r=await f.handler(f.req('/api/auth/google/start'),f.env);const cookie=r.headers.get('set-cookie').split(';')[0],url=new URL((await r.json()).url),state=url.searchParams.get('state');assert.equal(url.searchParams.get('scope'),'https://www.googleapis.com/auth/calendar.events');assert.equal(url.searchParams.get('code_challenge_method'),'S256');const cb='/api/auth/google/callback?state='+state+'&code=test';assert.equal((await f.handler(f.req(cb),f.env)).status,400);r=await f.handler(f.req(cb,undefined,{cookie}),f.env);assert.equal(r.status,303);assert.match(r.headers.get('location'),/calendar_connected=1/);assert.equal((await f.handler(f.req(cb,undefined,{cookie}),f.env)).status,400);const token=await decrypt(f.env,await f.env.Memory.get('google:tokens:user:alice'));assert.equal(token.refresh_token,'refresh');});
test('legacy direct POST prepares only and legacy chat confirmation cannot bypass review',async()=>{const f=fixture();await f.init();assert.equal((await f.handler(f.req('/api/calendar/events',event),f.env)).status,202);const r=await f.handler(f.req('/chat',{message:'CONFIRMAR EVENTO'}),f.env);assert.match((await r.json()).reply,/janela de revisão/);assert.equal(f.created.size,0);});
test('calendar reads, other integrations and production hosts are delegated unchanged',async()=>{const f=fixture(),paths=[];const original={scheduled(){return 7;},fetch:async request=>{paths.push(new URL(request.url).pathname);return new Response('existing');}},w=withCalendar(original,f.handler);for(const path of ['/calendar/events','/api/calendar/events','/health','/research'])assert.equal(await (await w.fetch(f.req(path),f.env)).text(),'existing');assert.equal(await(await w.fetch(new Request('https://mylumicompanion.com/calendar/events',{method:'POST'}),f.env)).text(),'existing');assert.equal(w.scheduled(),7);assert.equal(paths.length,5);});
test('app patch removes unsafe creation parser and preserves calendar reading block',()=>{const s='async function getReply(text) {\n const createCalendarRequest=true; unsafe();\n  const calendarRequest = true; return existingRead();\n}';const p=patchCalendarApp(s);assert.ok(!p.includes('unsafe()'));assert.ok(p.includes('const calendarRequest = true; return existingRead()'));assert.match(p,/Confirmar e criar evento/);assert.throws(()=>patchCalendarApp('unknown frontend'));});
test('review dialog displays explicit end and requires separate confirmation',async()=>{const dom=new JSDOM('<body></body>',{url:ORIGIN,runScripts:'outside-only'}),w=dom.window;w.HTMLDialogElement.prototype.showModal=function(){};w.HTMLDialogElement.prototype.close=function(){};w.eval(CALENDAR_FRONTEND);const calls=[];const request=async(url,o)=>{calls.push({url,body:JSON.parse(o.body)});return Response.json(url.endsWith('/prepare')?{created:false,requiresConfirmation:true,confirmationId:'a'.repeat(64),event:{...event,location:''}}:{created:true,event:{id:'id',title:event.title,start:event.start}});};const result=w.lumiCreateCalendarEvent('Marque dentista amanhã às 15h',request,ORIGIN+'/');const form=w.document.querySelector('form');assert.equal(form.elements.end.value,'');form.elements.title.value='Dentista';form.elements.start.value='17/10/2026 15:00';form.elements.end.value='17/10/2026 16:00';form.dispatchEvent(new w.Event('submit',{cancelable:true}));await new Promise(r=>setTimeout(r,20));assert.equal(calls.length,1);assert.equal(calls[0].url,ORIGIN+'/calendar/events/prepare');[...w.document.querySelectorAll('#lumiCalendarDialog > div button')].find(b=>b.textContent==='Confirmar e criar evento').click();const d=await result;assert.match(d.reply,/Evento criado/);assert.equal(calls.length,2);assert.equal(calls[1].body.confirmed,true);w.close();});
test('OAuth denied consent and insufficient granted scope never replace existing tokens',async()=>{for(const mode of ['denied','readonly']){const f=fixture();await f.init();const before=await f.env.Memory.get('google:tokens:user:alice');const r=await f.handler(f.req('/api/auth/google/start'),f.env),cookie=r.headers.get('set-cookie').split(';')[0],u=new URL((await r.json()).url);if(mode==='readonly')f.scope('https://www.googleapis.com/auth/calendar.readonly');const result=await f.handler(f.req('/api/auth/google/callback?state='+u.searchParams.get('state')+(mode==='denied'?'&error=access_denied':'&code=test'),undefined,{cookie}),f.env);assert.equal(result.status,mode==='denied'?400:403);assert.equal(await f.env.Memory.get('google:tokens:user:alice'),before);}});
test('invalid calendar dates, missing offsets, reversed dates and client authority are rejected',()=>{for(const change of [{start:'2026-10-17T15:00'},{start:'2027-02-30T15:00:00-03:00',end:'2027-03-03T15:00:00-03:00'},{end:event.start},{userId:'bob'},{attendees:['other@example.test']}])assert.throws(()=>validateEvent({...event,...change},time));});
test('cancel dialog and unrelated creation request never call Google create',async()=>{const dom=new JSDOM('<body></body>',{url:ORIGIN,runScripts:'outside-only'}),w=dom.window;w.HTMLDialogElement.prototype.showModal=function(){};w.HTMLDialogElement.prototype.close=function(){};w.eval(CALENDAR_FRONTEND);let calls=0;const p=w.lumiCreateCalendarEvent('Book appointment',async()=>{calls++;},ORIGIN+'/');w.document.querySelector('#lumiCalendarDialog > div button:last-child').click();assert.match((await p).reply,/Cancelled/);assert.equal(calls,0);w.close();});
test('OAuth return redirects directly into Lumi and restores only the authenticated owner event',async()=>{const f=fixture();const start=await f.handler(f.req('/api/auth/google/start',{resume:event}),f.env),cookie=start.headers.get('set-cookie').split(';')[0],state=new URL((await start.json()).url).searchParams.get('state');const cb=await f.handler(f.req('/api/auth/google/callback?state='+state+'&code=test',undefined,{cookie}),f.env);assert.equal(cb.status,303);const returnTo=new URL(cb.headers.get('location'));assert.equal(returnTo.origin,ORIGIN);assert.equal(returnTo.pathname,'/');const resumeId=returnTo.searchParams.get('calendar_resume');assert.equal(resumeId,state);f.user('bob');assert.equal((await f.handler(f.req('/calendar/events/resume',{resumeId}),f.env)).status,409);f.user('alice');const restored=await f.handler(f.req('/calendar/events/resume',{resumeId}),f.env);assert.equal(restored.status,200);assert.equal((await restored.json()).event.title,event.title);assert.equal(f.created.size,0);f.clock(time+600001);assert.equal((await f.handler(f.req('/calendar/events/resume',{resumeId}),f.env)).status,409);});
test('browser resumes event in Brazilian format, reaches review automatically, and Esc preserves it',async()=>{const f=fixture();const start=await f.handler(f.req('/api/auth/google/start',{resume:event}),f.env),cookie=start.headers.get('set-cookie').split(';')[0],state=new URL((await start.json()).url).searchParams.get('state');await f.handler(f.req('/api/auth/google/callback?state='+state+'&code=test',undefined,{cookie}),f.env);const dom=new JSDOM('<body></body>',{url:ORIGIN+'/?calendar_resume='+state,runScripts:'outside-only'}),w=dom.window;w.HTMLDialogElement.prototype.showModal=function(){};w.HTMLDialogElement.prototype.close=function(){};w.eval(CALENDAR_FRONTEND);const requests=[];const request=async(url,o)=>{requests.push(url);return f.handler(f.req(new URL(url).pathname,JSON.parse(o.body)),f.env);};const completed=w.lumiResumeCalendarEvent(request,ORIGIN+'/');await new Promise(r=>setTimeout(r,80));const dialog=w.document.getElementById('lumiCalendarDialog');assert.ok(dialog);assert.equal(dialog.querySelector('[name=start]').value,'17/10/2026 15:00');assert.equal(dialog.querySelector('[name=end]').value,'17/10/2026 16:00');assert.equal(dialog.querySelector('form').hidden,true);assert.match(dialog.querySelector('pre').textContent,/17\/10\/2026/);dialog.dispatchEvent(new w.Event('cancel',{cancelable:true}));assert.equal(w.document.getElementById('lumiCalendarDialog'),dialog);assert.equal(f.created.size,0);assert.ok(requests.every(x=>!x.endsWith('/confirm')));dialog.querySelector('div button:last-child').click();await completed;assert.equal(f.created.size,0);assert.equal(w.location.search,'');w.close();});
test('date and time picker buttons open the native widgets and preserve Brazilian values',async()=>{const dom=new JSDOM('<body></body>',{url:ORIGIN,runScripts:'outside-only'}),w=dom.window;w.HTMLDialogElement.prototype.showModal=function(){};w.HTMLDialogElement.prototype.close=function(){};const opened=[];w.HTMLInputElement.prototype.showPicker=function(){opened.push(this);};w.eval(CALENDAR_FRONTEND);const completed=w.lumiCreateCalendarEvent('Agende consulta',async()=>{throw Error('No request expected');},ORIGIN+'/');const dialog=w.document.getElementById('lumiCalendarDialog'),start=dialog.querySelector('[name=start]');start.value='17/10/2026 15:30';dialog.querySelector('[data-calendar-picker=start-date]').click();assert.equal(opened[0].type,'date');assert.equal(opened[0].value,'2026-10-17');opened[0].value='2026-10-20';opened[0].dispatchEvent(new w.Event('change'));assert.equal(start.value,'20/10/2026 15:30');dialog.querySelector('[data-calendar-picker=start-time]').click();assert.equal(opened[1].type,'time');opened[1].value='16:45';opened[1].dispatchEvent(new w.Event('change'));assert.equal(start.value,'20/10/2026 16:45');dialog.querySelector('[data-calendar-picker=end-date]').click();assert.equal(opened[2].value,'2026-10-20');delete w.HTMLInputElement.prototype.showPicker;dialog.querySelector('[data-calendar-picker=end-time]').click();const fallback=dialog.querySelectorAll('input[type=time]')[1];assert.equal(fallback.tabIndex,0);dialog.querySelector(':scope > div button:last-child').click();await completed;w.close();});
test('event end defaults to 30 minutes, accepts duration and gives explicit end precedence',()=>{const {end,...withoutEnd}=event;assert.equal(validateEvent(withoutEnd,time).end,'2026-10-17T18:30:00.000Z');assert.equal(validateEvent({...withoutEnd,durationMinutes:45},time).end,'2026-10-17T18:45:00.000Z');assert.equal(validateEvent({...event,durationMinutes:30},time).end,'2026-10-17T19:00:00.000Z');for(const durationMinutes of [0,-1,0.5,10081,'30'])assert.throws(()=>validateEvent({...withoutEnd,durationMinutes},time));});
test('dialog accepts blank end and prepares the selected duration, defaulting to 30 minutes',async()=>{for(const minutes of [30,45]){const dom=new JSDOM('<body></body>',{url:ORIGIN,runScripts:'outside-only'}),w=dom.window;w.HTMLDialogElement.prototype.showModal=function(){};w.HTMLDialogElement.prototype.close=function(){};w.eval(CALENDAR_FRONTEND);let prepared;const request=async(url,o)=>{const b=JSON.parse(o.body);if(url.endsWith('/prepare')){prepared=b;return Response.json({created:false,requiresConfirmation:true,confirmationId:'a'.repeat(64),event:b});}return Response.json({cancelled:true});};const done=w.lumiCreateCalendarEvent('Agende consulta',request,ORIGIN+'/'),form=w.document.querySelector('form');assert.equal(form.elements.end.required,false);assert.equal(form.elements.duration.value,'30');form.elements.title.value='Consulta';form.elements.start.value='17/10/2026 15:00';form.elements.duration.value=String(minutes);form.requestSubmit();await new Promise(r=>setTimeout(r,20));assert.equal(prepared.end,new Date(Date.parse('2026-10-17T18:00:00Z')+minutes*60000).toISOString());w.document.querySelector('#lumiCalendarDialog > div button:last-child').click();await done;w.close();}});
test('overlap warns before confirmation, cannot be bypassed without its review token and allows explicit override',async()=>{const f=fixture();f.items([{id:'busy',summary:'Consulta existente',start:{dateTime:'2026-10-17T18:15:00Z'},end:{dateTime:'2026-10-17T19:30:00Z'}}]);const d=await draft(f);assert.equal(d.conflicts.hasConflicts,true);assert.equal(d.conflicts.items[0].title,'Consulta existente');assert.equal(f.created.size,0);const confirmationId=d.confirmationId;let r=await f.handler(f.req('/calendar/events/confirm',{confirmationId,confirmed:true,allowConflicts:true}),f.env);assert.equal(r.status,409);const warned=await r.json();assert.equal(warned.code,'CALENDAR_CONFLICT');assert.equal(f.created.size,0);r=await f.handler(f.req('/calendar/events/confirm',{confirmationId,confirmed:true,allowConflicts:true,conflictToken:warned.conflicts.conflictToken}),f.env);assert.equal(r.status,200);assert.equal(f.created.size,1);const listing=f.calls.find(x=>x.url.includes('singleEvents'));const params=new URL(listing.url).searchParams;assert.equal(params.get('singleEvents'),'true');assert.equal(params.get('timeMin'),'2026-10-17T18:00:00.000Z');assert.equal(params.get('timeMax'),'2026-10-17T19:00:00.000Z');});
test('new or changed conflicts at confirmation require a new warning and explicit override',async()=>{const f=fixture(),d=await draft(f),confirmationId=d.confirmationId;f.items([{id:'later',summary:'Novo compromisso',start:{dateTime:'2026-10-17T18:10:00Z'},end:{dateTime:'2026-10-17T18:20:00Z'}}]);let r=await f.handler(f.req('/calendar/events/confirm',{confirmationId,confirmed:true}),f.env);assert.equal(r.status,409);const first=await r.json();f.items([{id:'different',summary:'Outro compromisso',start:{dateTime:'2026-10-17T18:30:00Z'},end:{dateTime:'2026-10-17T18:40:00Z'}}]);r=await f.handler(f.req('/calendar/events/confirm',{confirmationId,confirmed:true,allowConflicts:true,conflictToken:first.conflicts.conflictToken}),f.env);assert.equal(r.status,409);const second=await r.json();assert.notEqual(first.conflicts.conflictToken,second.conflicts.conflictToken);assert.equal(f.created.size,0);r=await f.handler(f.req('/calendar/events/confirm',{confirmationId,confirmed:true,allowConflicts:true,conflictToken:second.conflicts.conflictToken}),f.env);assert.equal(r.status,200);assert.equal(f.created.size,1);});
test('all-day busy events warn; adjacent, free, cancelled and self-declined events do not block',async()=>{const f=fixture();f.items([{id:'all-day',summary:'Dia ocupado',start:{date:'2026-10-17'},end:{date:'2026-10-18'}},{id:'adjacent-before',start:{dateTime:'2026-10-17T17:00:00Z'},end:{dateTime:'2026-10-17T18:00:00Z'}},{id:'adjacent-after',start:{dateTime:'2026-10-17T19:00:00Z'},end:{dateTime:'2026-10-17T20:00:00Z'}},{id:'free',transparency:'transparent'},{id:'cancelled',status:'cancelled'},{id:'declined',attendees:[{self:true,responseStatus:'declined'}]}]);const d=await draft(f);assert.equal(d.conflicts.count,1);assert.equal(d.conflicts.items[0].allDay,true);});
test('lookup failures and malformed calendar intervals do not produce false free-time assurances',async()=>{const f=fixture();await f.init();f.failure(500);let r=await f.handler(f.req('/calendar/events/prepare',event),f.env);assert.equal(r.status,503);assert.equal((await r.json()).code,'CHECK');f.failure(0);f.items([{id:'malformed',start:{},end:{}}]);r=await f.handler(f.req('/calendar/events/prepare',event),f.env);assert.equal(r.status,503);assert.equal(f.created.size,0);});
test('calendar lookup follows pagination and handles all-day boundaries in calendar timezone',async()=>{const {findConflicts,calendarMidnight,overlaps}=await import('../../lumi-calendar/calendar-conflicts.mjs');assert.equal(calendarMidnight('2026-10-17','America/New_York'),Date.parse('2026-10-17T04:00:00Z'));assert.equal(overlaps({start:{date:'2026-10-17'},end:{date:'2026-10-18'}},{start:'2026-10-18T03:30:00Z',end:'2026-10-18T03:45:00Z'},'America/New_York'),true);assert.equal(overlaps({start:{date:'2026-10-17'},end:{date:'2026-10-18'}},{start:'2026-10-18T04:00:00Z',end:'2026-10-18T04:30:00Z'},'America/New_York'),false);const urls=[],google=async url=>{urls.push(url);return Response.json(urls.length===1?{items:[],nextPageToken:'page2'}:{items:[{id:'recurring-instance',summary:'Recorrente',start:{dateTime:event.start},end:{dateTime:event.end}}]});};const conflicts=await findConflicts(event,{google,accessToken:'test'});assert.equal(conflicts.length,1);assert.equal(new URL(urls[1]).searchParams.get('pageToken'),'page2');await assert.rejects(findConflicts(event,{google:async()=>Response.json({items:[],nextPageToken:'still-more'}),accessToken:'test'}),/pagination/);});
test('conflict dialog offers another time without creating, then confirms a free revised slot',async()=>{const f=fixture();await f.init();f.items([{id:'busy',summary:'<img src=x> Consulta',start:{dateTime:event.start},end:{dateTime:event.end}}]);const dom=new JSDOM('<body></body>',{url:ORIGIN,runScripts:'outside-only'}),w=dom.window;w.HTMLDialogElement.prototype.showModal=function(){};w.HTMLDialogElement.prototype.close=function(){};w.eval(CALENDAR_FRONTEND);const requests=[],request=async(url,o)=>{requests.push({url,body:JSON.parse(o.body)});return f.handler(f.req(new URL(url).pathname,JSON.parse(o.body)),f.env);};const done=w.lumiCreateCalendarEvent('Agende consulta',request,ORIGIN+'/'),form=w.document.querySelector('form');form.elements.title.value='Consulta';form.elements.start.value='17/10/2026 15:00';form.requestSubmit();await new Promise(r=>setTimeout(r,30));const box=w.document.getElementById('lumiCalendarConflicts');assert.match(box.textContent,/Conflito de horário/);assert.equal(box.querySelector('img'),null);const button=text=>[...w.document.querySelectorAll('button')].find(x=>x.textContent===text);assert.equal(button('Criar mesmo assim').hidden,false);assert.equal(f.created.size,0);button('Escolher outro horário').click();assert.equal(form.hidden,false);form.elements.start.value='17/10/2026 17:00';form.requestSubmit();await new Promise(r=>setTimeout(r,30));assert.match(box.textContent,/Nenhum conflito/);button('Confirmar e criar evento').click();await done;assert.equal(f.created.size,1);assert.equal(requests.filter(x=>x.url.endsWith('/confirm')).length,1);w.close();});
test('browser requires a second explicit click if conflicts appear after review',async()=>{const f=fixture();await f.init();const dom=new JSDOM('<body></body>',{url:ORIGIN,runScripts:'outside-only'}),w=dom.window;w.HTMLDialogElement.prototype.showModal=function(){};w.HTMLDialogElement.prototype.close=function(){};w.eval(CALENDAR_FRONTEND);const sent=[],request=async(url,o)=>{sent.push(JSON.parse(o.body));return f.handler(f.req(new URL(url).pathname,JSON.parse(o.body)),f.env);};const done=w.lumiCreateCalendarEvent('Agende consulta',request,ORIGIN+'/'),form=w.document.querySelector('form');form.elements.title.value='Consulta';form.elements.start.value='17/10/2026 15:00';form.requestSubmit();await new Promise(r=>setTimeout(r,30));f.items([{id:'new-busy',summary:'Mudança na agenda',start:{dateTime:event.start},end:{dateTime:event.end}}]);const button=text=>[...w.document.querySelectorAll('button')].find(x=>x.textContent===text);button('Confirmar e criar evento').click();await new Promise(r=>setTimeout(r,30));assert.equal(f.created.size,0);assert.match(w.document.getElementById('lumiCalendarConflicts').textContent,/Mudança na agenda/);button('Criar mesmo assim').click();await done;assert.equal(f.created.size,1);assert.equal(sent.at(-1).allowConflicts,true);assert.equal(typeof sent.at(-1).conflictToken,'string');w.close();});
