test('daily agenda requires authentication, accepts read-only permission and uses Brasilia day boundaries',async()=>{const f=fixture();await f.init();f.scope('https://www.googleapis.com/auth/calendar.readonly');f.items([{id:'free',summary:'Disponível',transparency:'transparent',start:{dateTime:event.start},end:{dateTime:event.end}},{id:'all-day',summary:'Dia inteiro',start:{date:'2026-10-17'},end:{date:'2026-10-18'}},{id:'removed',status:'cancelled'}]);let r=await f.handler(f.req('/calendar/events/day',{date:'2026-10-17'},{authorization:''}),f.env);assert.equal(r.status,401);r=await f.handler(f.req('/calendar/events/day',{date:'2026-10-17'}),f.env);assert.equal(r.status,200);const data=await r.json();assert.equal(data.events.length,2);assert.equal(data.events.find(x=>x.id==='all-day').allDay,true);const query=new URL(f.calls.find(x=>x.url.includes('orderBy')).url).searchParams;assert.equal(query.get('timeMin'),'2026-10-17T03:00:00.000Z');assert.equal(query.get('timeMax'),'2026-10-18T03:00:00.000Z');assert.equal(query.get('singleEvents'),'true');for(const body of [{date:'2026-02-30'},{date:'17/10/2026'},{date:'2026-10-17',calendarId:'other'}])assert.equal((await f.handler(f.req('/calendar/events/day',body),f.env)).status,400);assert.equal(f.created.size,0);});
