test('Brazilian day/month requests prefill the requested date and do not leave command/date in title',async()=>{for(const text of ['criar dia 21/10 às 11h','Criar consulta dia 21/10/2026 às 11:00']){const dom=new JSDOM('<body></body>',{url:ORIGIN,runScripts:'outside-only'}),w=dom.window;w.HTMLDialogElement.prototype.showModal=function(){};w.HTMLDialogElement.prototype.close=function(){};w.eval(CALENDAR_FRONTEND);const done=w.lumiCreateCalendarEvent(text,async()=>{throw Error('No request expected');},ORIGIN+'/'),form=w.document.querySelector('form'),year=new Intl.DateTimeFormat('en',{timeZone:'America/Sao_Paulo',year:'numeric'}).format(new Date());assert.equal(form.elements.start.value,'21/10/'+(text.includes('/2026')?'2026':year)+' 11:00');assert.equal(form.elements.title.value,text.includes('consulta')?'consulta':'');w.document.querySelector('#lumiCalendarDialog > div button:last-child').click();await done;w.close();}});
