test('missing local session becomes clickable sign-in and preserves the exact event across login navigation',async()=>{const first=new JSDOM('<body><button id="signInBtn">Sign in</button></body>',{url:ORIGIN,runScripts:'outside-only'}),a=first.window;a.HTMLDialogElement.prototype.showModal=function(){};a.HTMLDialogElement.prototype.close=function(){};a.lumiSessionOwner='alice';a.eval(CALENDAR_FRONTEND);let clicks=0;a.document.getElementById('signInBtn').onclick=()=>clicks++;const before=a.lumiCreateCalendarEvent('criar evento 17/10/2026 as 14:30 Com Aline Prieto',async()=>{throw Error('Please sign in to continue.');},ORIGIN+'/'),form=a.document.querySelector('form');assert.equal(form.elements.start.value,'17/10/2026 14:30');form.requestSubmit();await new Promise(r=>setTimeout(r,20));[...a.document.querySelectorAll('button')].find(b=>b.textContent==='Entre na Lumi para continuar').click();assert.equal(clicks,1);const saved=a.sessionStorage.getItem('lumiCalendarSignInDraft');assert.ok(saved);first.window.close();
 const second=new JSDOM('<body></body>',{url:ORIGIN,runScripts:'outside-only'}),w=second.window;w.HTMLDialogElement.prototype.showModal=function(){};w.HTMLDialogElement.prototype.close=function(){};w.sessionStorage.setItem('lumiCalendarSignInDraft',saved);w.eval(CALENDAR_FRONTEND);const calls=[],request=async(url,o)=>{calls.push(url);const body=JSON.parse(o.body);return Response.json(url.endsWith('/prepare')?{created:false,requiresConfirmation:true,confirmationId:'a'.repeat(64),event:body}:{cancelled:true});};await w.lumiResumeCalendarSignIn(request,ORIGIN+'/',async()=>({id:'alice'}));await new Promise(r=>setTimeout(r,30));const resumed=w.document.querySelector('form');assert.equal(resumed.elements.start.value,'17/10/2026 14:30');assert.equal(resumed.elements.duration.value,'30');assert.match(resumed.elements.title.value,/Com Aline Prieto/);assert.equal(resumed.hidden,true);assert.equal(calls.length,1);assert.ok(calls[0].endsWith('/prepare'));assert.equal(w.sessionStorage.getItem('lumiCalendarSignInDraft'),null);w.document.querySelector('#lumiCalendarDialog > div button:last-child').click();await new Promise(r=>setTimeout(r,10));w.close();});
test('login resumption waits for verified session and expires rather than restoring indefinitely',async()=>{const dom=new JSDOM('<body><button id="signInBtn">Sign in</button></body>',{url:ORIGIN,runScripts:'outside-only'}),w=dom.window;w.HTMLDialogElement.prototype.showModal=function(){};w.HTMLDialogElement.prototype.close=function(){};w.eval(CALENDAR_FRONTEND);const fields={title:'Consulta',start:'17/10/2026 14:30',end:'',duration:'30',location:''};let requests=0;w.sessionStorage.setItem('lumiCalendarSignInDraft',JSON.stringify({owner:'alice',fields,expiresAt:Date.now()+600000}));await w.lumiResumeCalendarSignIn(async()=>{requests++;},ORIGIN+'/',async()=>null);assert.equal(w.document.querySelector('#lumiCalendarDialog'),null);assert.match(w.document.getElementById('lumiCalendarLoginResume').textContent,/Entre na Lumi/);assert.equal(requests,0);w.sessionStorage.setItem('lumiCalendarSignInDraft',JSON.stringify({owner:'alice',fields,expiresAt:Date.now()-1}));await w.lumiResumeCalendarSignIn(async()=>{requests++;},ORIGIN+'/',async()=>({id:'alice'}));assert.equal(w.sessionStorage.getItem('lumiCalendarSignInDraft'),null);assert.equal(requests,0);w.close();});
test('complete Calendar flow works with Cloudflare redirect constraints and actual auth verifier',async()=>{const f=fixture();Object.assign(f.env,{SUPABASE_URL:'https://example.supabase.co',SUPABASE_PUBLISHABLE_KEY:'sb_publishable_test'});await f.init();let userChecks=0;const fetcher=async(url,o={})=>{if(o.redirect==='error')throw new TypeError('Invalid redirect value');assert.equal(o.redirect,'manual');if(url==='https://example.supabase.co/auth/v1/user'){userChecks++;assert.equal(o.headers.authorization,'Bearer valid-session');return Response.json({id:'alice'});}if(url.includes('tokeninfo'))return Response.json({aud:'client',scope:'https://www.googleapis.com/auth/calendar.events'});if(o.method==='POST'){const p=JSON.parse(o.body);return Response.json(p);}return Response.json({items:[],timeZone:'America/Sao_Paulo'});};const handle=createCalendarHandler({fetcher,now:()=>time});const prep=await handle(f.req('/calendar/events/prepare',event),f.env);assert.equal(prep.status,202);const d=await prep.json(),confirmed=await handle(f.req('/calendar/events/confirm',{confirmationId:d.confirmationId,confirmed:true}),f.env);assert.equal(confirmed.status,200);assert.equal((await confirmed.json()).created,true);assert.equal(userChecks,2);});
test('Google redirects cannot forward calendar credentials',async()=>{const f=fixture();await f.init();let calls=0;const handler=createCalendarHandler({now:()=>time,verify:async()=>({id:'alice'}),fetcher:async(url,o)=>{calls++;assert.equal(o.redirect,'manual');return new Response(null,{status:302,headers:{location:'https://foreign.example/'}});}});const r=await handler(f.req('/calendar/events/prepare',event),f.env);assert.equal(r.status,502);assert.equal(calls,1);assert.equal(f.created.size,0);});
test('standalone Agenda reads today and other dates without inventing a created event or writing Calendar',async()=>{const dom=new JSDOM('<body><div id="messages"></div></body>',{url:ORIGIN,runScripts:'outside-only'}),w=dom.window;w.eval(CALENDAR_FRONTEND);const calls=[],request=async(url,options)=>{calls.push({url,body:JSON.parse(options.body)});return Response.json({events:[{id:'existing',title:'Compromisso existente',start:event.start,end:event.end}]});};await w.lumiShowCalendarDay(null,request,ORIGIN+'/');const panel=w.document.getElementById('lumiCalendarDay');assert.match(panel.textContent,/Compromisso existente/);assert.doesNotMatch(panel.textContent,/Evento confirmado/);assert.equal(panel.querySelectorAll('[data-created=true]').length,0);assert.equal(calls.length,1);assert.ok(calls[0].url.endsWith('/calendar/events/day'));const date=panel.querySelector('input');date.value='2026-10-18';date.dispatchEvent(new w.Event('change'));await new Promise(r=>setTimeout(r,10));assert.equal(calls.at(-1).body.date,'2026-10-18');assert.ok(calls.every(c=>c.url.endsWith('/calendar/events/day')));w.close();});
test('standalone Agenda failure offers retry without claiming an event was created',async()=>{const dom=new JSDOM('<body><div id="messages"></div></body>',{url:ORIGIN,runScripts:'outside-only'}),w=dom.window;w.eval(CALENDAR_FRONTEND);await w.lumiShowCalendarDay(null,async()=>Response.json({error:'Indisponível'},{status:503}),ORIGIN+'/');const panel=w.document.getElementById('lumiCalendarDay');assert.match(panel.textContent,/Não consegui carregar a agenda/);assert.doesNotMatch(panel.textContent,/O evento está confirmado/);assert.ok([...panel.querySelectorAll('button')].some(b=>b.textContent==='Atualizar agenda'));w.close();});
test('weekly agenda reads Monday through Sunday with one read-only Google query',async()=>{const f=fixture();await f.init();f.scope('https://www.googleapis.com/auth/calendar.readonly');f.items([{id:'existing',summary:'Externo à Lumi',start:{dateTime:event.start},end:{dateTime:event.end}}]);const response=await f.handler(f.req('/calendar/events/week',{date:'2026-10-18'}),f.env);assert.equal(response.status,200);const data=await response.json();assert.equal(data.weekStart,'2026-10-12');assert.equal(data.weekEndExclusive,'2026-10-19');assert.equal(data.events[0].title,'Externo à Lumi');const reads=f.calls.filter(x=>x.url.includes('orderBy'));assert.equal(reads.length,1);const params=new URL(reads[0].url).searchParams;assert.equal(params.get('timeMin'),'2026-10-12T03:00:00.000Z');assert.equal(params.get('timeMax'),'2026-10-19T03:00:00.000Z');assert.equal(f.created.size,0);assert.equal((await f.handler(f.req('/calendar/events/week',{date:'2026-10-18'},{authorization:''}),f.env)).status,401);});
