test('weekly frontend groups seven days, handles spanning events and resets to the current week whenever reopened',async()=>{const dom=new JSDOM('<body><div id="messages"></div></body>',{url:ORIGIN,runScripts:'outside-only'}),w=dom.window;w.AbortSignal=AbortSignal;w.eval(CALENDAR_FRONTEND);const calls=[];const request=async(url,o)=>{const {date}=JSON.parse(o.body);calls.push({url,date});return Response.json({events:[{id:'all',title:'Evento de dois dias',allDay:true,start:date,end:new Date(Date.parse(date+'T12:00:00Z')+2*86400000).toISOString().slice(0,10)},{id:'timed',title:'Horário normal',start:date+'T14:00:00-03:00',end:date+'T14:30:00-03:00'}]});};await w.lumiShowCalendarWeek(request,ORIGIN+'/');const first=calls[0].date;assert.equal(new Date(first+'T12:00:00Z').getUTCDay(),1);assert.equal(w.document.querySelectorAll('[data-agenda-day]').length,7);assert.equal([...w.document.querySelectorAll('#lumiCalendarWeek article')].filter(n=>n.textContent.includes('Evento de dois dias')).length,2);assert.match(w.document.getElementById('lumiCalendarWeek').textContent,/14:00 – 14:30/);const date=w.document.querySelector('#lumiCalendarWeek input');date.value='2026-01-01';date.dispatchEvent(new w.Event('change'));await new Promise(r=>setTimeout(r,10));assert.equal(calls.at(-1).date,'2025-12-29');await w.lumiShowCalendarWeek(request,ORIGIN+'/');assert.equal(calls.at(-1).date,first);assert.equal(w.document.querySelectorAll('#lumiCalendarWeek').length,1);assert.ok(calls.every(c=>c.url.endsWith('/calendar/events/week')));assert.doesNotMatch(w.document.getElementById('lumiCalendarWeek').textContent,/Evento confirmado/);w.close();});
test('weekly agenda automatically starts Google authorization and keeps Lumi sign-in separate',async()=>{const dom=new JSDOM('<body><button id="signInBtn">Sign in</button><div id="messages"></div></body>',{url:ORIGIN,runScripts:'outside-only'}),w=dom.window;w.AbortSignal=AbortSignal;w.eval(CALENDAR_FRONTEND);let signedIn=0;w.document.getElementById('signInBtn').onclick=()=>signedIn++;const calls=[],request=async(url,o)=>{calls.push({url,body:JSON.parse(o.body)});return url.endsWith('/week')?Response.json({code:'CONNECT',error:'Conecte o Calendar'},{status:403}):Response.json({code:'AUTH',error:'Entre na Lumi para continuar'},{status:401});};await w.lumiShowCalendarWeek(request,ORIGIN+'/');assert.ok(![...w.document.querySelectorAll('#lumiCalendarWeek button')].some(b=>b.textContent==='Conectar Google Calendar'));const login=[...w.document.querySelectorAll('#lumiCalendarWeek button')].find(b=>b.textContent==='Entre na Lumi para continuar');assert.ok(login);login.click();assert.equal(signedIn,1);assert.ok(calls[1].url.endsWith('/auth/google/start'));assert.deepEqual(calls[1].body,{});assert.equal(calls.some(c=>/prepare|confirm/.test(c.url)),false);w.close();});
test('legacy pending event is recovered only for its owner without creating it',async()=>{const f=fixture();await f.init();f.map.set('calendar:pending:user:alice',JSON.stringify(event));const r=await f.handler(f.req('/calendar/events/pending',{}),f.env);assert.equal(r.status,200);assert.equal((await r.json()).event.title,event.title);f.user('bob');assert.equal((await (await f.handler(f.req('/calendar/events/pending',{}),f.env)).json()).event,null);assert.equal((await f.handler(f.req('/calendar/events/pending',{}, {authorization:''}),f.env)).status,401);assert.equal(f.created.size,0);assert.equal(f.calls.length,0);});
test('confirmation typos open review with the original event and never write automatically',async()=>{for(const text of ['Comfirmar','COMFIRMAR EVENTO','CONFIRMAR EVENTO','confirmar']){const dom=new JSDOM('<body></body>',{url:ORIGIN,runScripts:'outside-only'}),w=dom.window;w.HTMLDialogElement.prototype.showModal=function(){this.open=true;};w.HTMLDialogElement.prototype.close=function(){};w.eval(CALENDAR_FRONTEND);let restored;w.lumiCreateCalendarEvent=async(text,request,base,event)=>{restored=event;return {reply:'review'};};const patched=patchCalendarApp('async function getReply(text) {\n  const calendarRequest = false;\n}');const start=patched.indexOf('async function getReply(text)'),end=patched.indexOf('  const calendarRequest =',start);w.eval(patched.slice(start,end)+'return {}; }');w.authFetch=async()=>Response.json({created:false,event});w.WORKER_URL=ORIGIN+'/';await w.getReply(text);assert.equal(restored.title,event.title);w.close();}});
const symposiumProposal=`Recebi o link e confirmo os dados:
- Título: Simpósio Parkinson (GAP) — inscrição gratuita
- Data/hora: 24/10/2026 — 07:30 a 12:45 (America/Sao_Paulo)
- Local/Descrição: https://www.e-inscricao.com/simposioparkinson/vsimposio
Para preparar o evento, responda exatamente: CONFIRMAR EVENTO.`;
test('expired KV draft recovers symposium title, times and link from authenticated history',async()=>{const f=fixture();f.map.set('history:user:alice',JSON.stringify([{role:'assistant',content:symposiumProposal},{role:'user',content:'Comfirmar evento'}]));const r=await f.handler(f.req('/calendar/events/pending',{}),f.env),d=await r.json();assert.equal(r.status,200);assert.equal(d.event.title,'Simpósio Parkinson (GAP) — inscrição gratuita');assert.equal(d.event.start,'2026-10-24T10:30:00.000Z');assert.equal(d.event.end,'2026-10-24T15:45:00.000Z');assert.match(d.event.description,/e-inscricao/);assert.equal(f.created.size,0);f.user('bob');assert.equal((await (await f.handler(f.req('/calendar/events/pending',{}),f.env)).json()).event,null);});
test('complete chat proposal becomes short reply plus structured review without a magic phrase',async()=>{const f=fixture(),worker=withCalendar({fetch:async()=>Response.json({reply:symposiumProposal})},f.handler);const r=await worker.fetch(f.req('/chat',{message:'link'}),f.env),d=await r.json();assert.equal(d.reply,'Revise os dados e toque em Confirmar e criar evento.');assert.equal(d.calendarEvent.title,'Simpósio Parkinson (GAP) — inscrição gratuita');assert.equal(f.created.size,0);});
test('assembled getReply opens structured proposal directly rather than displaying legacy instructions',async()=>{const {readFileSync}=await import('node:fs');const source=patchCalendarApp(readFileSync(new URL('../../app.js',import.meta.url),'utf8')),start=source.indexOf('async function getReply(text)'),end=source.indexOf('\n  return data;\n}',start)+'\n  return data;\n}'.length;let restored;const getReply=new Function('authFetch','WORKER_URL','state','lumiCreateCalendarEvent',source.slice(start,end)+';return getReply;')(async()=>Response.json({reply:symposiumProposal,calendarEvent:event}),ORIGIN+'/',{messages:[]},async(text,request,base,data)=>{restored=data;return {reply:'review'};});assert.equal((await getReply('https://www.e-inscricao.com/simposioparkinson/vsimposio')).reply,'review');assert.equal(restored.title,event.title);});

const neuroProposal=`Ok — dados que vou usar:  - Título: Consulta com neurologista   - Data: 26/10/2026   - Horário: 17:00–18:00 (1 hora) — fuso America/Sao_Paulo (UTC−03:00)   - Presencial — local a confirmar  Se estiver tudo certo, responda exatamente (maiúsculas, sem acento): CONFIRMAR EVENTO`;
test('one-line and split-field proposals recover the current neurologist visit instead of an earlier symposium',async()=>{const {calendarProposal}=await import('../../lumi-calendar/calendar-conversation.mjs');for(const proposal of [neuroProposal,neuroProposal.replaceAll('   - ','\n- ')]){const e=calendarProposal(proposal);assert.equal(e.title,'Consulta com neurologista');assert.equal(e.start,'2026-10-26T17:00:00-03:00');assert.equal(e.end,'2026-10-26T18:00:00-03:00');}const f=fixture();f.map.set('calendar:pending:user:alice',JSON.stringify(event));f.map.set('history:user:alice',JSON.stringify([{role:'assistant',content:symposiumProposal},{role:'user',content:'me marca consulta de neurologista'},{role:'assistant',content:neuroProposal},{role:'user',content:'Presencial'}]));const r=await f.handler(f.req('/calendar/events/pending',{}),f.env),data=await r.json();assert.equal(data.event.title,'Consulta com neurologista');assert.equal(data.event.start,'2026-10-26T20:00:00.000Z');assert.equal(f.created.size,0);});
test('inline symposium proposals open review and do not absorb following labels into the title',async()=>{const {calendarProposal}=await import('../../lumi-calendar/calendar-conversation.mjs');const proposal=symposiumProposal.replaceAll('\n',' '),e=calendarProposal(proposal);assert.equal(e.title,'Simpósio Parkinson (GAP) — inscrição gratuita');assert.equal(e.end,'2026-10-24T12:45:00-03:00');const f=fixture(),worker=withCalendar({fetch:async()=>Response.json({reply:neuroProposal})},f.handler);const d=await(await worker.fetch(f.req('/chat',{message:'Presencial'}),f.env)).json();assert.equal(d.calendarEvent.title,'Consulta com neurologista');assert.equal(d.reply,'Revise os dados e toque em Confirmar e criar evento.');});

test('spoken marca request prefills appointment title and accepts seventeen hs without trailing command words',async()=>{const dom=new JSDOM('<body></body>',{url:ORIGIN,runScripts:'outside-only'}),w=dom.window;w.HTMLDialogElement.prototype.showModal=function(){};w.HTMLDialogElement.prototype.close=function(){};w.eval(CALENDAR_FRONTEND);const done=w.lumiCreateCalendarEvent('Oi Luane me marca uma consulta de neurologista 26/10/2026 as 17 hs',async()=>{throw Error('No request expected before review');},ORIGIN+'/');const form=w.document.querySelector('form');assert.equal(form.elements.title.value,'consulta de neurologista');assert.equal(form.elements.start.value,'26/10/2026 17:00');assert.equal(form.elements.duration.value,'30');w.document.querySelector('#lumiCalendarDialog > div button:last-child').click();await done;w.close();});


